public class ExpenseDbContext(DbContextOptions<ExpenseDbContext> options) : DbContext(options)
{
    public DbSet<ExpenseReport> ExpenseReports => Set<ExpenseReport>();
    public DbSet<LineItem> LineItems => Set<LineItem>();
    public DbSet<Organization> Organizations => Set<Organization>();
    public DbSet<Department> Departments => Set<Department>();
    public DbSet<PolicyRule> PolicyRules => Set<PolicyRule>();

    protected override void OnModelCreating(ModelBuilder model)
    {
        model.ApplyConfigurationsFromAssembly(typeof(ExpenseDbContext).Assembly);

        model.Entity<ExpenseReport>(e =>
        {
            e.ToTable("ExpenseReports");
            e.HasKey(x => x.Id);
            e.Property(x => x.Id)
                .ValueGeneratedOnAdd()
                .HasDefaultValueSql("NEWSEQUENTIALID()");
            e.OwnsOne(x => x.TotalAmount, money =>
            {
                money.Property(p => p.Amount).HasColumnName("TotalAmount");
                money.Property(p => p.Currency).HasColumnName("Currency");
            });
            e.HasIndex(x => new { x.OrganizationId, x.Status })
                .HasFilter("IsDeleted = 0");
            e.HasMany(x => x.LineItems)
                .WithOne()
                .HasForeignKey(x => x.ExpenseReportId)
                .OnDelete(DeleteBehavior.Cascade);
            e.HasMany(x => x.Approvals)
                .WithOne()
                .HasForeignKey(x => x.ExpenseReportId)
                .OnDelete(DeleteBehavior.Restrict);
        });

        model.Entity<LineItem>(e =>
        {
            e.ToTable("LineItems");
            e.HasKey(x => x.Id);
            e.Property(x => x.Id).UseIdentityColumn();
            e.Property(x => x.Category)
                .HasConversion<string>()
                .HasMaxLength(50);
            e.Property(x => x.Amount).HasColumnType("DECIMAL(18,2)");
            e.HasIndex(x => x.ExpenseReportId);
        });

        model.Entity<Organization>(e =>
        {
            e.ToTable("Organizations");
            e.HasIndex(x => x.Slug).IsUnique();
        });

        model.Entity<PolicyRule>(e =>
        {
            e.ToTable("PolicyRules");
            e.HasIndex(x => new { x.OrganizationId, x.Category })
                .HasFilter("IsDeleted = 0 AND IsActive = 1");
        });
    }
}

public interface IUnitOfWork : IDisposable, IAsyncDisposable
{
    Task<ITransaction> BeginTransactionAsync(CancellationToken ct = default);
    Task<int> SaveChangesAsync(CancellationToken ct = default);
}

public sealed class EfCoreUnitOfWork(ExpenseDbContext db) : IUnitOfWork
{
    public async Task<ITransaction> BeginTransactionAsync(CancellationToken ct = default)
    {
        var tx = await db.Database.BeginTransactionAsync(ct);
        return new EfCoreTransaction(tx);
    }

    public async Task<int> SaveChangesAsync(CancellationToken ct = default)
    {
        return await db.SaveChangesAsync(ct);
    }

    public void Dispose() => db.Dispose();
    public async ValueTask DisposeAsync() => await db.DisposeAsync();
}

public sealed class EfCoreTransaction : ITransaction
{
    private readonly IDbContextTransaction _tx;
    public EfCoreTransaction(IDbContextTransaction tx) => _tx = tx;
    public async Task CommitAsync(CancellationToken ct = default)
        => await _tx.CommitAsync(ct);
    public async Task RollbackAsync(CancellationToken ct = default)
        => await _tx.RollbackAsync(ct);
    public ValueTask DisposeAsync() => _tx.DisposeAsync();
}

public static class DbSeeder
{
    public static async Task SeedAsync(ExpenseDbContext db, CancellationToken ct)
    {
        if (!await db.Organizations.AnyAsync(ct))
        {
            var org = new Organization("Acme Corp", "acme-corp", Currency.USD);
            db.Organizations.Add(org);

            var travel = new PolicyRule(org.Id, LineItemCategory.Travel, maxAmount: 500m, requiresReceipt: true);
            var meals = new PolicyRule(org.Id, LineItemCategory.Meals, maxAmount: 75m, requiresReceipt: false);
            db.PolicyRules.AddRange([travel, meals]);

            await db.SaveChangesAsync(ct);
        }
    }
}
